<?php $id = get_the_ID(); $image = igp_product_image( $id ); ?>
<article class="radiator-card"><a href="<?php the_permalink(); ?>" class="radiator-photo" aria-label="<?php echo esc_attr( get_the_title() ); ?>"><?php if ( $image ) : ?><img src="<?php echo esc_url( $image ); ?>" width="612" height="408" loading="lazy" alt="<?php echo esc_attr( has_post_thumbnail() ? get_the_title() : get_post_meta( $id, '_acc_material', true ) . ' representative radiator' ); ?>"><?php endif; ?></a><div class="radiator-info"><p class="part-code"><?php echo esc_html( get_post_meta( $id, '_igp_part_number', true ) ); ?></p><h3><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h3><p><?php echo esc_html( get_post_meta( $id, '_acc_material', true ) ); ?></p><a class="text-link" href="<?php the_permalink(); ?>">Specifications <span aria-hidden="true">↗</span></a></div></article>
